250	/// Parse a bare `type Name;` item.
251	#[expect(dead_code)]
252	pub struct BareType {
253	    pub attrs: Vec<Attribute>,
254	    pub type_token: Token![type],
255	    pub ident: Ident,
256	    pub semi_token: Token![;],
257	}
258	
259	impl Parse for BareType {
260	    fn parse(input: ParseStream) -> Result<Self> {
261	        Ok(Self {
262	            attrs: input.call(Attribute::parse_outer)?,
263	            type_token: input.parse()?,
264	            ident: input.parse()?,
265	            semi_token: input.parse()?,
266	        })
267	    }
268	}
